    module alu_16bit (
    input wire clk,
    input wire rst,
    input wire [15:0] a,
    input wire [15:0] b,
    input wire [3:0] opcode,
    output reg [15:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Combinational logic for operations
    reg [15:0] temp_result;
    reg temp_overflow;
    
    always @(*) begin
        temp_overflow = 1'b0;
        case (opcode)
            4'b0000: // ADD
                begin
                    temp_result = a + b;
                    temp_overflow = (a[15] == b[15] && a[15] != temp_result[15]);
                end
            4'b0001: // SUB
                begin
                    temp_result = a - b;
                    temp_overflow = (a[15] != b[15] && a[15] != temp_result[15]);
                end
            4'b0010: // AND
                temp_result = a & b;
            4'b0011: // OR
                temp_result = a | b;
            default:
                temp_result = 0;
        endcase
    end
    
    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result <= 0;
            zero <= 0;
            overflow <= 0;
            negative <= 0;
        end else begin
            result <= temp_result;
            zero <= (temp_result == 0);
            overflow <= temp_overflow;
            negative <= temp_result[15];
        end
    end

endmodule